create table public.user_blocks (blocker_id uuid not null references public.users(id) on delete cascade, blocked_id uuid not null references public.users(id) on delete cascade, created_at timestamptz not null default now(), primary key (blocker_id, blocked_id), check (blocker_id <> blocked_id));
create table public.reports (id uuid primary key default gen_random_uuid(), reporter_id uuid not null references public.users(id), reported_id uuid not null references public.users(id), job_id uuid references public.jobs(id), reason text not null check (char_length(reason) between 3 and 1000), status text not null default 'open' check (status in ('open','resolved','dismissed')), created_at timestamptz not null default now());
create table public.job_attendance_reports (job_id uuid not null references public.jobs(id) on delete cascade, worker_id uuid not null references public.users(id), employer_id uuid not null references public.users(id), status text not null check (status in ('present','no_show')), created_at timestamptz not null default now(), primary key(job_id, worker_id));
alter table public.user_blocks enable row level security; alter table public.reports enable row level security; alter table public.job_attendance_reports enable row level security;
